(1, NULL, NULL, 'Cross-Border trade & expansion opportunities', 'EThis eBook takes you on a tour of the current export landscape of India. Know about the global expansion opportunities for your eCommerce business.', 'website_images/book-1.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'Active', '2026-05-16 13:11:53', '2026-05-16 14:02:36'),
(2, NULL, NULL, 'Get started with hyperlocal delivery', 'The pandemic brought about a drastic shift in the buying process. People now shop online even for basic requirements. Learn about hyperlocal deliveries and how you can start with them.', 'website_images/book-3.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 'Active', '2026-05-16 13:11:53', '2026-05-16 13:11:53'),
(3, NULL, NULL, 'Master strategies for eCommerce business management', 'Get your hands on exclusive techniques and expert ideas about how to manage your eCommerce business efficiently.', 'website_images/book-2.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'Active', '2026-05-16 13:11:53', '2026-05-16 13:11:53'),
(4, 'hero', 'hero_content', 'eBooks for  <span class=\"moving-gradient-text\">Exporters</span>', NULL, 'website_images/1785305277_e-books.webp', NULL, NULL, NULL, 'Read our ebooks', NULL, NULL, NULL, 'Must-read guides, handpicked for their popularity among global exporters', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"eBooks for  <span class=\\\"moving-gradient-text\\\">Exporters<\\/span>1\",\"description\":null,\"image\":\"website_images\\/1785305277_e-books.webp\",\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":\"Read our ebooks\",\"button_text\":null,\"button_url\":null,\"btn_text\":null,\"subtitle\":\"Must-read guides, handpicked for their popularity among global exporters\",\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 1, 'Active', '2026-05-16 13:27:29', '2026-07-29 06:08:40'),
(5, 'section_header', 'section_header_content', 'Grow your knowledge to grow your business', 'EGet your hands on our eBooks and learn about everything required to grow your business. Be it marketing, sales, logistics, or social media. Access the A to Z guides for guaranteed business growth.. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Grow your knowledge to grow your business11\",\"description\":\"EGet your hands on our eBooks and learn about everything required to grow your business. Be it marketing, sales, logistics, or social media. Access the A to Z guides for guaranteed business growth.. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.\",\"image\":null,\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":null,\"button_text\":null,\"button_url\":null,\"btn_text\":null,\"subtitle\":null,\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 1, 'Active', '2026-05-16 13:27:29', '2026-07-23 09:54:17');
INSERT INTO `ecommerce_logistics_solutions_page` (`id`, `section`, `item_key`, `content`, `icon_svg`, `icon_class`, `color_scheme`, `badge_text`, `button_text`, `button_url`, `btn_text`, `subtitle`, `paragraphs`, `question`, `answer`, `name`, `avatar_url`, `rating`, `text_content`, `stat_value`, `stat_label`, `stat_suffix`, `logo_url`, `alt_text`, `list_items_text`, `check_list_text`, `extra_content`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'hero_main', '{\"title\":\"Your Store. Our Logistics. <span class=\\\"moving-gradient-text\\\">Infinite Growth<\\/span>\",\"description\":\"You built the store. You crushed the sales. Now comes the hard part, i.e., shipping. However, it shouldn\\u2019t be hard from now on. Connect your marketplace to us and watch the magic happen.\",\"image\":\"images\\/1785314273_1784790136_supply-chain.webp\"}', NULL, NULL, NULL, 'E-commerce Logistics Solutions', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"button_primary_text\":\"Book a Shipment\",\"button_primary_icon\":\"fa-paper-plane\",\"button_primary_url\":\".\\/login\",\"button_secondary_text\":\"Get a Quote\",\"button_secondary_icon\":\"fa-calculator\",\"button_secondary_url\":\".\\/get-started\",\"badges\":[{\"icon\":\"fa-clock\",\"text\":\"24\\u201372 Hr Delivery\"},{\"icon\":\"fa-shield-alt\",\"text\":\"Fully Insured\"},{\"icon\":\"fa-map-marker-alt\",\"text\":\"220+ Countries\"}],\"stat_pills\":[{\"icon\":\"fa-box\",\"value\":\"50K+\",\"label\":\"Shipments\\/Month\",\"color\":\"rgba(26,115,232,.1)\",\"text_color\":\"var(--primary)\"},{\"icon\":\"fa-star\",\"value\":\"4.9\\u2605\",\"label\":\"Avg Rating\",\"color\":\"rgba(255,107,0,.1)\",\"text_color\":\"var(--accent)\"},{\"icon\":\"fa-check-circle\",\"value\":\"99.2%\",\"label\":\"On-Time Rate\",\"color\":\"rgba(40,167,69,.1)\",\"text_color\":\"var(--success)\"}]}', 1, 1, '2026-05-14 04:19:36', '2026-08-14 09:54:57'),
