INSERT INTO `home_page` (`id`, `section`, `field_name`, `content`, `sort_order`, `updated_at`) VALUES
(223, 'shipping_solutions', 'heading', 'Shipping Solutions Designed Around You!', 0, '2026-07-28 11:15:51'),
(224, 'shipping_solutions', 'description', 'No two businesses ship the same way. That\'s why United Worldwide Couriers offers flexible logistics solutions built around your shipment type, delivery timeline, budget, and business goals. Whether you need B2B Export Support, Dropshipping Solutions, Marketplace shipping, or personal deliveries for friends and family, we help you choose the right service with clarity, reliability, and complete support.', 0, '2026-07-28 11:16:18'),
(225, 'shipping_solutions', 'card_title', 'B2B Shipping Made Simple', 1, '2026-07-28 11:16:57'),
(226, 'shipping_solutions', 'card_desc', 'Move commercial shipments with confidence. We support exporters, manufacturers, distributors, and growing businesses with secure handling, flexible delivery options, documentation support, and competitive pricing for bulk volumes.', 1, '2026-05-20 04:21:55'),
(227, 'shipping_solutions', 'card_point1', 'Fragile Goods: <span style=\"font-weight: 400;\">Secure handling for sensitive and high-volume shipments<span>', 1, '2026-05-26 06:15:11'),
(228, 'shipping_solutions', 'card_point2', 'Bulk Shipments: <span style=\"font-weight: 400;\">Cost-effective solutions and customs clearance support.<span>', 1, '2026-05-26 06:16:55'),
(229, 'shipping_solutions', 'card_cta', 'Start Shipping', 1, '2026-05-08 03:37:23'),
(230, 'shipping_solutions', 'card_title', 'Marketplace Shipping', 3, '2026-05-19 07:01:21'),
(231, 'shipping_solutions', 'card_desc', 'Connect your online store with our shipping platform and manage orders from leading marketplaces like Amazon, eBay, Etsy, Walmart, and more, with faster processing, real-time tracking, and reliable delivery support.', 3, '2026-05-26 18:17:03'),
(232, 'shipping_solutions', 'card_point1', 'End-to-End Support: <span style=\"font-weight:400\">Manage multiple tasks with one easy-to-use dashboard.</span>', 2, '2026-05-26 06:27:09'),
(233, 'shipping_solutions', 'card_point2', 'Automated Order flow: <span style=\"font-weight:400\">Manage. Process. Dispatch.</span>', 2, '2026-05-26 06:27:59'),
(234, 'shipping_solutions', 'card_cta', 'Start Shipping', 2, '2026-05-08 03:37:23'),
(235, 'shipping_solutions', 'card_title', 'Dropshipping Solutions', 2, '2026-05-19 07:01:42'),
(236, 'shipping_solutions', 'card_desc', 'Launch and scale your online business with reliable door-to-door shipping. Whether you sell through Shopify, your own website, or a dropshiping store, we help you ship products directly to customers with speed, tracking and complete reliability.', 2, '2026-08-12 09:19:15'),
(237, 'shipping_solutions', 'card_point1', 'Real-Time Tracking: <span style=\"font-weight:400\">Complete visibility for every shipment.<span>', 3, '2026-05-26 06:26:08'),
(238, 'shipping_solutions', 'card_point2', 'Seller-Friendly Shipping:  <span style=\"font-weight:400\">Built for marketplace sellers handling small packages daily and high volume.</span>', 3, '2026-05-26 06:23:20'),
(239, 'shipping_solutions', 'card_cta', 'Start Shipping', 3, '2026-05-08 03:37:23'),
(240, 'shipping_solutions', 'card_title', 'Overseas Friends & Family', 4, '2026-05-08 03:37:23'),
(241, 'shipping_solutions', 'card_desc', 'Send personal packages to your loved ones worldwide with safe handling, timely delivery, and clear updates at every step.', 4, '2026-05-08 03:37:23'),
(242, 'shipping_solutions', 'card_point1', 'International Delivery: <span style=\"font-weight:400\">Reliable shipping for gifts, documents, clothes, and personal items.</span>', 4, '2026-05-26 06:20:13'),
(243, 'shipping_solutions', 'card_point2', 'Live Updates: <span style=\"font-weight:400\">Stay informed from pickup to delivery.</span>', 4, '2026-05-26 06:20:34'),
(244, 'shipping_solutions', 'card_cta', 'Start Shipping', 4, '2026-05-26 02:25:43'),
