(1, 'hero', 'hero_content', 'Track Your <span class=\"moving-gradient-text\">Orders Easily</span>', NULL, 'website_images/tracking.webp', NULL, NULL, NULL, 'Free Tool · Instant Results', 'Track Now', NULL, NULL, 'Just enter your Mobile Number, AWB tracking number or Order ID & it\'s done.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Track Your <span class=\\\"moving-gradient-text\\\">Orders Easily<\\/span>\",\"description\":\"Just enter your Mobile Number, AWB tracking number or Order ID & it\'s done.\",\"image\":\"website_images\\/tracking.webp\",\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"button_text\":\"Track Now1\",\"button_url\":null,\"btn_text\":null,\"subtitle\":\"Just enter your Mobile Number, AWB tracking number or Order ID & it\'s done.\",\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 1, 'Active', '2026-05-16 14:44:36', '2026-07-24 09:35:00'),
(2, 'track_form', 'track_form_content', 'AWB Number', NULL, NULL, NULL, NULL, NULL, NULL, 'Track Now', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"field_1_label\":\"AWB Number\",\"field_1_placeholder\":\"Airway Bill Number\",\"field_2_label\":\"Order Id\",\"field_2_placeholder\":\"eg: 983434599\",\"field_3_label\":\"Phone Number\",\"field_3_placeholder\":\"+91 9876543210\"}', NULL, '{\"title\":\"Tracks <span class=\\\"gradient-text\\\">Now<\\/span>\",\"description\":null,\"image\":null,\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":null,\"button_text\":\"Track Now\",\"button_url\":null,\"btn_text\":null,\"subtitle\":null,\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null,\"field_1_label\":\"AWB Number\",\"field_1_placeholder\":\"Airway Bill Number\",\"field_2_label\":\"Order Id\",\"field_2_placeholder\":\"eg: 983434599\",\"field_3_label\":\"Phone Number\",\"field_3_placeholder\":\"+91 9876543210\"}', 2, 'Active', '2026-05-16 14:44:36', '2026-06-03 03:21:00'),
(3, 'features', 'features_header', 'What\'s your order status?', 'Carriers use dimensional weight to price large, light packages — here\'s what you need to know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"What\'s your order status?\",\"description\":\"Carriers use dimensional weight to price large, light packages \\u2014 here\'s what you need to know.\",\"image\":null,\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":null,\"button_text\":null,\"button_url\":null,\"btn_text\":null,\"subtitle\":null,\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 1, 'Active', '2026-05-16 14:44:36', '2026-07-29 06:00:56'),
(4, 'features', 'feature_1', 'Order Placed', 'Your order has been successfully placed and is being processed by the seller.', NULL, 'fa-solid fa-check-to-slot', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"blue\",\"icon_color_code\":\"#2563eb\"}', NULL, '{\"icon_color\":\"blue\",\"icon\":\"fa-solid fa-check-to-slot\",\"icon_color_code\":\"#2563eb\",\"title\":\"Order Placed\",\"description\":\"Your order has been successfully placed and is being processed by the seller.\"}', 2, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(5, 'features', 'feature_2', 'Order Confirmed', 'Seller has confirmed your order and it\'s being prepared for shipment.', NULL, 'fa-solid fa-box-open', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"orange\",\"icon_color_code\":\"#f59e0b\"}', NULL, '{\"icon_color\":\"orange\",\"icon\":\"fa-solid fa-box-open\",\"icon_color_code\":\"#f59e0b\",\"title\":\"Order Confirmed\",\"description\":\"Seller has confirmed your order and it\'s being prepared for shipment.\"}', 3, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(6, 'features', 'feature_3', 'In Transit', 'Your package is on its way and moving through the delivery network.', NULL, 'fa-solid fa-truck', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"green\",\"icon_color_code\":\"#10b981\"}', NULL, '{\"icon_color\":\"green\",\"icon\":\"fa-solid fa-truck\",\"icon_color_code\":\"#10b981\",\"title\":\"In Transit\",\"description\":\"Your package is on its way and moving through the delivery network.\"}', 4, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(7, 'features', 'feature_4', 'Delivered', 'Your package has been delivered successfully. Thank you for your patience!', NULL, 'fa-solid fa-circle-check', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"purple\",\"icon_color_code\":\"#8b5cf6\"}', NULL, '{\"icon_color\":\"purple\",\"icon\":\"fa-solid fa-circle-check\",\"icon_color_code\":\"#8b5cf6\",\"title\":\"Delivered\",\"description\":\"Your package has been delivered successfully. Thank you for your patience!\"}', 5, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(8, 'about', 'about_content', 'Optimize your order <span class=\"gradient-text\">tracking experience</span>', 'Always stay informed about your shipments, regardless of your courier partner', NULL, NULL, NULL, NULL, NULL, 'Need help?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Real-time tracking updates across all major carriers\r\nEnd-to-end visibility from pickup to delivery', '{\"button_link\":\"contact-us.php\",\"video_url\":\"https:\\/\\/www.youtube.com\\/embed\\/5mRQQj7iHRY?si=qW7E_eV31xEAMG7Q\"}', 'contact-us.php', '{\"title\":\"Optimize your order <span class=\\\"gradient-text\\\">tracking experience<\\/span>\",\"description\":\"Always stay informed about your shipments, regardless of your courier partner\",\"image\":null,\"link\":\"contact-us.php\",\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":null,\"button_text\":\"Need help?\",\"button_url\":null,\"btn_text\":null,\"subtitle\":null,\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null,\"check_list\":\"Real-time tracking updates across all major carriers\\r\\nEnd-to-end visibility from pickup to delivery\",\"button_link\":\"contact-us.php\",\"video_url\":\"https:\\/\\/www.youtube.com\\/embed\\/5mRQQj7iHRY?si=qW7E_eV31xEAMG7Q\"}', 1, 'Active', '2026-05-16 14:44:36', '2026-07-29 06:00:19'),
(9, 'cta', 'cta_content', 'Need any help related order??', 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, NULL, 'Get in Touch', 'Contact Us Now →', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"button_link\":\"#\"}', '#', '{\"badge_text\":\"Get in Touch\",\"title\":\"Need any help related order??\",\"description\":\"Get live updates across all major carriers \\u2014 end-to-end visibility from pickup to delivery for every order you export worldwide.\",\"button_text\":\"Contact Us Now \\u2192\",\"button_link\":\"#\"}', 1, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36');
INSERT INTO `volumetric_calculator_page` (`id`, `page`, `section`, `data_title`, `data_description`, `data_icon`, `data_image`, `data_link`, `data_button_text`, `data_extra`, `data`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'volumetric-calculator', 'hero', 'Volumetric <span class=\"moving-gradient-text\">Weight Calculator</span>', 'Instantly calculate dimensional weight and understand how carriers charge for package size, not just weight.', NULL, 'assets/images/1785306141_volumetric-weight.webp', NULL, 'Calculate Now', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"button_url\":\"#calcualte_section\"}', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"title\":\"Volumetric <span class=\\\"moving-gradient-text\\\">Weight Calculator<\\/span>\",\"description\":\"Instantly calculate dimensional weight and understand how carriers charge for package size, not just weight.\",\"button_text\":\"Calculate Now\",\"button_url\":\"#calcualte_section\",\"image\":\"assets\\/images\\/1785306141_volumetric-weight.webp\"}', 1, 1, '2026-05-11 23:34:05', '2026-08-13 04:22:42'),
(2, 'volumetric-calculator', 'features_header', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":null,\"description\":null}', 2, 0, '2026-05-11 23:34:05', '2026-08-13 04:42:05'),
(3, 'volumetric-calculator', 'features', 'Measure all three dimensions', 'Measure the length, width, and height of the package in centimetres using tape. Always measure the outer dimensions, including packaging material, to ensure accurate calculations.', 'fa-solid fa-ruler', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-ruler\"}', '{\"icon_class\":\"fa-solid fa-ruler\",\"title\":\"Measure all three dimensions\",\"description\":\"Measure the length, width, and height of the package in centimetres using tape. Always measure the outer dimensions, including packaging material, to ensure accurate calculations.\"}', 3, 1, '2026-05-11 23:34:05', '2026-07-28 13:24:38'),
(4, 'volumetric-calculator', 'features', 'Apply the divisor formula', 'Multiply length × width × height to get the cubic volume, then divide by the carrier\'s divisor to get the package\'s volumetric weight.', 'fa-solid fa-divide', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-divide\"}', '{\"icon_class\":\"fa-solid fa-divide\",\"title\":\"Apply the divisor formula\",\"description\":\"Multiply length \\u00d7 width \\u00d7 height to get the cubic volume, then divide by the carrier\'s divisor to get the package\'s volumetric weight.\"}', 4, 1, '2026-05-11 23:34:05', '2026-07-28 13:25:12'),
(5, 'volumetric-calculator', 'features', 'Compare with actual weight', 'The higher value between  actual weight and volumetric weight is charged. Know both to optimize packaging, reduce dimensions, and lower shipping costs on every shipment.', 'fa-solid fa-scale-balanced', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-scale-balanced\"}', '{\"icon_class\":\"fa-solid fa-scale-balanced\",\"title\":\"Compare with actual weight\",\"description\":\"The higher value between  actual weight and volumetric weight is charged. Know both to optimize packaging, reduce dimensions, and lower shipping costs on every shipment.\"}', 5, 1, '2026-05-11 23:34:05', '2026-08-13 04:27:08'),
(6, 'volumetric-calculator', 'track_cta', 'Track any shipment in real-times', 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, 'Track Shipment →', '{\"live_badge\":\"\\u25cf LIVE TRACKING\",\"button_url\":\".\\/tracking\"}', '{\"live_badge\":\"\\u25cf LIVE TRACKING\",\"title\":\"Track any shipment in real-times\",\"description\":\"Get live updates across all major carriers \\u2014 end-to-end visibility from pickup to delivery for every order you export worldwide.\",\"button_text\":\"Track Shipment \\u2192\",\"button_url\":\".\\/tracking\"}', 6, 1, '2026-05-11 23:34:05', '2026-08-13 04:44:18'),
