(8, 'overview', 'overview_main', '{\"title\":\"Store - Track - Ship - Repeat\",\"paragraphs\":\"Take control of your entire supply chain with our warehousing solutions. Businesses can keep the inventory in secure spaces with professional oversight over the goods. Track every item or shipment in real-time with advanced inventory systems. Ship with confidence knowing your goods are organized and accessible 24\\/7. Overall, United Worldwide Courier\\u2019s platform eliminates the complexities involved, reduces delays, and keeps the business moving.\",\"image\":\"assets\\/images\\/1785314455_united-warehouse.webp\",\"list_items\":[\"Live visibility of inventory from the warehouse to the customer\'s doorstep.\",\"Advanced inventory management systems that know exactly where everything is.\",\"Quick order processing and dispatch without delays or errors.\",\"Dashboard for managing orders across all sales channels.\",\"Ship through multiple carriers with optimized routing and rates.\",\"Storage and fulfillment capacity.\"],\"button_text\":null,\"button_url\":\"#\"}', NULL, NULL, NULL, NULL, 'Book Shipments', '#', NULL, NULL, 'Take control of your entire supply chain with our warehousing solutions. Businesses can keep the inventory in secure spaces with professional oversight over the goods. Track every item or shipment in real-time with advanced inventory systems. Ship with confidence knowing your goods are organized and accessible 24/7. Overall, United Worldwide Courier’s platform eliminates the complexities involved, reduces delays, and keeps the business moving.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Live visibility of inventory from the warehouse to the customer\'s doorstep.\nAdvanced inventory management systems that know exactly where everything is.\nQuick order processing and dispatch without delays or errors.\nDashboard for managing orders across all sales channels.\nShip through multiple carriers with optimized routing and rates.\nStorage and fulfillment capacity.', NULL, '{\"title\":\"Store. Manage. Fulfil\\u2014Smarter from The USA\",\"image\":\"images\\/map-pattern.png\"}', 12, 1, '2026-05-13 22:11:13', '2026-08-12 09:50:53'),
(9, 'features', 'features_header', '{\"title\":\"Transforming Inventory Management Into Your Advantage\",\"subtitle\":\"Powering your business with cutting-edge logistics technology and unmatched service quality.\",\"description\":null,\"paragraphs\":\"Lost stock, disorganized shelves, inventory mismatches, poor visibility - these are some frustrations that may cost your business time, money, and operational efficiency. Our warehousing solution is built specifically to eliminate each one of them. Experience the difference when your inventory works as hard as your business does.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Powering your business with cutting-edge logistics technology and unmatched service quality.', 'Lost stock, disorganized shelves, inventory mismatches, poor visibility - these are some frustrations that may cost your business time, money, and operational efficiency. Our warehousing solution is built specifically to eliminate each one of them. Experience the difference when your inventory works as hard as your business does.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"What Makes Our E-commerce Logistics Stand Out\"}', 13, 1, '2026-05-13 22:11:13', '2026-08-12 09:48:06'),
(10, 'features', 'feature_tracking', '{\"subtitle\":\"Quality Assurance Protocols\",\"paragraphs\":\"With regular inspections, damage assessments, and compliance checks, we maintain the condition of goods from storage to shipment.\",\"icon_svg\":\"<i class=\\\"fas fa-satellite\\\"><\\/i>\",\"icon_class\":\"fi-blue\"}', '<i class=\"fas fa-satellite\"></i>', 'fi-blue', NULL, NULL, NULL, NULL, NULL, 'Quality Assurance Protocols', 'With regular inspections, damage assessments, and compliance checks, we maintain the condition of goods from storage to shipment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 14, 1, '2026-05-13 22:11:13', '2026-08-12 09:48:47'),
(11, 'features', 'feature_temperature', '{\"subtitle\":\"Automated Stock Optimization\",\"paragraphs\":\"Control overstock and stockouts with smart demand-based inventory management.\",\"icon_svg\":\"<i class=\\\"fas fa-thermometer-half\\\"><\\/i>\",\"icon_class\":\"fi-orange\"}', '<i class=\"fas fa-thermometer-half\"></i>', 'fi-orange', NULL, NULL, NULL, NULL, NULL, 'Automated Stock Optimization', 'Control overstock and stockouts with smart demand-based inventory management.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 15, 1, '2026-05-13 22:11:13', '2026-05-30 04:13:25'),
(12, 'features', 'feature_support', '{\"subtitle\":\"Monitoring and Security\",\"paragraphs\":\"24\\/7 surveillance and security systems ensure goods are protected from damage, theft, or loss.\",\"icon_svg\":\"<i class=\\\"fas fa-headset\\\"><\\/i>\",\"icon_class\":\"fi-navy\"}', '<i class=\"fas fa-headset\"></i>', 'fi-navy', NULL, NULL, NULL, NULL, NULL, 'Monitoring and Security', '24/7 surveillance and security systems ensure goods are protected from damage, theft, or loss.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 1, '2026-05-13 22:11:13', '2026-05-30 04:14:43'),
(13, 'features', 'feature_eco', '{\"subtitle\":\"Multi-Channel Inclusion\",\"paragraphs\":\"Businesses can sync inventory across all sales channels (e-commerce, marketplace, retail) with complete visibility.\",\"icon_svg\":\"<i class=\\\"fas fa-leaf\\\"><\\/i>\",\"icon_class\":\"fi-green\"}', '<i class=\"fas fa-leaf\"></i>', 'fi-green', NULL, NULL, NULL, NULL, NULL, 'Multi-Channel Inclusion', 'Businesses can sync inventory across all sales channels (e-commerce, marketplace, retail) with complete visibility.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 17, 1, '2026-05-13 22:11:13', '2026-08-12 09:50:15'),
(14, 'testimonials', 'testimonials_header', '{\"title\":\"Trusted by the Brands You Trust\",\"paragraphs\":\"Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Trusted by the Brands You Trust\"}', 18, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(15, 'testimonials', 'testimonial_1', '{\"subtitle\":\"Shelly Kapoor\",\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-1.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Shelly Kapoor', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-1.png\"}', 19, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(16, 'testimonials', 'testimonial_2', '{\"subtitle\":\"Vansh Agarwal\",\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-2.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vansh Agarwal', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-2.png\"}', 20, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(17, 'testimonials', 'testimonial_3', '{\"subtitle\":\"Rahul Mehta\",\"description\":\"Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.\",\"image\":\"images\\/review-3.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Rahul Mehta', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.\",\"image\":\"images\\/review-3.png\"}', 21, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
