(11, 'features', 'features_header', 'Importance of World Time Tracking', 'People use world time tools to stay synchronized across different countries and regions. Whether for travel, business meetings, or communication, knowing the exact time in another location is essential. A world time calculator helps users easily check and compare time zones, ensuring better planning and coordination globally.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', 11, 'Active', '2026-05-18 01:00:18', '2026-05-18 01:00:18'),
(12, 'features', 'feature_card_1', 'Real-time Global Time', 'Get accurate and up-to-date current time from any country or city around the world instantly.', NULL, 'fa-clock', NULL, 'feat-blue', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon\":\"fa-clock\",\"color_class\":\"feat-blue\"}', 12, 'Active', '2026-05-18 01:00:18', '2026-05-18 01:00:18'),
(13, 'features', 'feature_card_2', 'Worldwide Coverage', 'Access time zones from all over the globe and stay connected no matter where you are.', NULL, 'fa-globe', NULL, 'feat-purple', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon\":\"fa-globe\",\"color_class\":\"feat-purple\"}', 13, 'Active', '2026-05-18 01:00:18', '2026-05-18 01:00:18'),
